<?php if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("INSERT INTO vendors(code,name,category,email,phone,status) VALUES(?,?,?,?,?,'Pending')");$s->execute([$_POST['code'],$_POST['name'],$_POST['category'],$_POST['email'],$_POST['phone']]);echo'<div class="alert alert-success">Vendor berhasil ditambahkan.</div>';}$rows=$pdo->query("SELECT * FROM vendors ORDER BY id DESC")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Vendor Management</h2><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#addVendor">+ Vendor</button></div><div class="card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Code</th><th>Vendor</th><th>Category</th><th>Contact</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['code']?></td><td><?=$r['name']?></td><td><?=$r['category']?></td><td><?=$r['email']?><br><?=$r['phone']?></td><td><?=$r['status']?></td></tr><?php endforeach;?></tbody></table></div></div><div class="modal fade" id="addVendor"><div class="modal-dialog"><div class="modal-content"><form method="post"><div class="modal-header"><h5>Add Vendor</h5></div><div class="modal-body"><?php foreach(['code'=>'Vendor Code','name'=>'Vendor Name','category'=>'Category','email'=>'Email','phone'=>'Phone'] as $n=>$l):?><label class="form-label"><?=$l?></label><input name="<?=$n?>" class="form-control mb-2" required><?php endforeach;?></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div></div>